local NetMendingNeedleMaker = {}
local PRODUCTS = {
    iron_netmendingneedle = { name = "Železni igla za krpanje mrež", ironCost = 3, woodCost = 2, leatherCost = 1, time = 5, cost = 150, prestige = 4, happiness = 2, description = "Železni igla za krpanje mrež za ribištvo." },
    bronze_netmendingneedle = { name = "Bronast igla za krpanje mrež", bronzeCost = 3, ironCost = 1, woodCost = 2, leatherCost = 1, time = 7, cost = 365, prestige = 6, happiness = 3, description = "Bronast igla za krpanje mrež za ribištvo." },
    silver_netmendingneedle = { name = "Srebrn igla za krpanje mrež", silverCost = 3, bronzeCost = 1, ironCost = 1, woodCost = 2, leatherCost = 1, time = 11, cost = 880, prestige = 11, happiness = 4, description = "Srebrn igla za krpanje mrež za ribištvo." },
    gilded_netmendingneedle = { name = "Pozlačen igla za krpanje mrež", goldCost = 1, silverCost = 3, bronzeCost = 1, woodCost = 2, leatherCost = 1, time = 15, cost = 1900, prestige = 20, happiness = 5, description = "Pozlačen igla za krpanje mrež za ribištvo." },
    jewel_set_netmendingneedle = { name = "Draguljast igla za krpanje mrež", goldCost = 2, silverCost = 3, jewelCost = 1, bronzeCost = 1, woodCost = 2, leatherCost = 1, time = 19, cost = 4100, prestige = 36, happiness = 7, description = "Draguljast igla za krpanje mrež za ribištvo." },
    royal_sovereign_netmendingneedle = { name = "Kraljevski suveren igla za krpanje mrež", goldCost = 3, silverCost = 3, jewelCost = 2, pearlCost = 2, bronzeCost = 1, woodCost = 3, leatherCost = 1, time = 26, cost = 8800, prestige = 68, happiness = 13, description = "Suveren igla za krpanje mrež z biseri za krono." },
}
local BUILDINGS = {
    netmendingneedle_workshop = { name = "Netmendingneedle delavnica", cost = { gold = 325, wood = 185, stone = 130, iron = 7 }, upkeep = 6, qualityBonus = 5 },
    netmendingneedle_house = { name = "Netmendingneedle hiša", cost = { gold = 1185, wood = 370, stone = 265, silver = 7, iron = 7 }, upkeep = 25, qualityBonus = 18 },
    master_netmendingneedle_atelier = { name = "Mojstrski netmendingneedle atelje", cost = { gold = 2975, wood = 425, stone = 515, silver = 35, gold = 7 }, upkeep = 70, qualityBonus = 30 },
    sovereign_netmendingneedle_palace = { name = "Suverena netmendingneedle palača", cost = { gold = 12920, wood = 650, stone = 825, gold = 83, jewel = 19 }, upkeep = 253, qualityBonus = 55, prestigeBonus = 50 },
}
NetMendingNeedleMaker.ironStock = 16; NetMendingNeedleMaker.bronzeStock = 14; NetMendingNeedleMaker.woodStock = 10; NetMendingNeedleMaker.leatherStock = 8; NetMendingNeedleMaker.silverStock = 8; NetMendingNeedleMaker.goldStock = 6; NetMendingNeedleMaker.jewelStock = 4; NetMendingNeedleMaker.pearlStock = 4
NetMendingNeedleMaker.productStock = {}; NetMendingNeedleMaker.buildings = {}; NetMendingNeedleMaker.maker = nil; NetMendingNeedleMaker.activeMaking = {}; NetMendingNeedleMaker.totalProducts = 0; NetMendingNeedleMaker.dayTimer = 0
function NetMendingNeedleMaker.init() NetMendingNeedleMaker.ironStock=16; NetMendingNeedleMaker.bronzeStock=14; NetMendingNeedleMaker.woodStock=10; NetMendingNeedleMaker.leatherStock=8; NetMendingNeedleMaker.silverStock=8; NetMendingNeedleMaker.goldStock=6; NetMendingNeedleMaker.jewelStock=4; NetMendingNeedleMaker.pearlStock=4; NetMendingNeedleMaker.productStock={}; NetMendingNeedleMaker.buildings={}; NetMendingNeedleMaker.maker=nil; NetMendingNeedleMaker.activeMaking={}; NetMendingNeedleMaker.totalProducts=0; NetMendingNeedleMaker.dayTimer=0; print("[NetMendingNeedleMaker] Royal Net Mending Needle Maker System initialized (6 products, 4 buildings)") end
function NetMendingNeedleMaker.hireMaker(n,s) s=s or math.random(55,90); local c=585+s*12; if not _G.state or (_G.state.gold or 0)<c then return false,"Premalo zlata" end; _G.state.gold=_G.state.gold-c; NetMendingNeedleMaker.maker={name=n or ("Iglec "..math.random(1,99)),skill=s,hiredDay=os.time(),itemsMade=0}; if _G.NotificationCenter then pcall(_G.NotificationCenter.notify,string.format("Iglec najet: %s (spretnost: %d)",NetMendingNeedleMaker.maker.name,s),"success") end; return true end
function NetMendingNeedleMaker.canBuild(id) local d=BUILDINGS[id]; if not d then return false,"Neznana zgradba" end; if not _G.state then return false,"Brez stanja" end; if _G.state.gold<(d.cost.gold or 0) then return false,"Premalo zlata" end; if _G.state.resources then for r,a in pairs(d.cost) do if r~="gold" and (_G.state.resources[r] or 0)<a then return false,"Premalo "..r end end end; return true end
function NetMendingNeedleMaker.build(id) local ok,e=NetMendingNeedleMaker.canBuild(id); if not ok then return false,e end; local d=BUILDINGS[id]; _G.state.gold=_G.state.gold-(d.cost.gold or 0); if _G.state.resources then for r,a in pairs(d.cost) do if r~="gold" then _G.state.resources[r]=(_G.state.resources[r] or 0)-a end end end; table.insert(NetMendingNeedleMaker.buildings,{type=id,builtDay=os.time()}); if _G.NotificationCenter then pcall(_G.NotificationCenter.notify,"Zgrajeno: "..d.name,"success") end; return true end
function NetMendingNeedleMaker.getQualityBonus() local b=0; for _,bd in ipairs(NetMendingNeedleMaker.buildings) do local d=BUILDINGS[bd.type]; if d and d.qualityBonus then b=b+d.qualityBonus end end; return b end
function NetMendingNeedleMaker.canMake(pt) local d=PRODUCTS[pt]; if not d then return false,"Neznan produkt" end; if d.ironCost and NetMendingNeedleMaker.ironStock<(d.ironCost or 0) then return false,"Premalo železa" end; if d.bronzeCost and NetMendingNeedleMaker.bronzeStock<(d.bronzeCost or 0) then return false,"Premalo brona" end; if d.woodCost and NetMendingNeedleMaker.woodStock<(d.woodCost or 0) then return false,"Premalo lesa" end; if d.leatherCost and NetMendingNeedleMaker.leatherStock<(d.leatherCost or 0) then return false,"Premalo usnja" end; if d.silverCost and NetMendingNeedleMaker.silverStock<(d.silverCost or 0) then return false,"Premalo srebra" end; if d.goldCost and NetMendingNeedleMaker.goldStock<(d.goldCost or 0) then return false,"Premalo zlata" end; if d.jewelCost and NetMendingNeedleMaker.jewelStock<(d.jewelCost or 0) then return false,"Premalo draguljev" end; if d.pearlCost and NetMendingNeedleMaker.pearlStock<(d.pearlCost or 0) then return false,"Premalo biserov" end; if #NetMendingNeedleMaker.buildings==0 then return false,"Potrebna iglena delavnica" end; if not NetMendingNeedleMaker.maker then return false,"Potreben iglec" end; return true end
function NetMendingNeedleMaker.make(pt,qty) qty=qty or 1; local ok,e=NetMendingNeedleMaker.canMake(pt); if not ok then return false,e end; local d=PRODUCTS[pt]; if d.ironCost then NetMendingNeedleMaker.ironStock=NetMendingNeedleMaker.ironStock-d.ironCost*qty end; if d.bronzeCost then NetMendingNeedleMaker.bronzeStock=NetMendingNeedleMaker.bronzeStock-d.bronzeCost*qty end; if d.woodCost then NetMendingNeedleMaker.woodStock=NetMendingNeedleMaker.woodStock-d.woodCost*qty end; if d.leatherCost then NetMendingNeedleMaker.leatherStock=NetMendingNeedleMaker.leatherStock-d.leatherCost*qty end; if d.silverCost then NetMendingNeedleMaker.silverStock=NetMendingNeedleMaker.silverStock-d.silverCost*qty end; if d.goldCost then NetMendingNeedleMaker.goldStock=NetMendingNeedleMaker.goldStock-d.goldCost*qty end; if d.jewelCost then NetMendingNeedleMaker.jewelStock=NetMendingNeedleMaker.jewelStock-d.jewelCost*qty end; if d.pearlCost then NetMendingNeedleMaker.pearlStock=NetMendingNeedleMaker.pearlStock-d.pearlCost*qty end; local t=d.time; if NetMendingNeedleMaker.maker then t=math.max(1,t-math.floor(NetMendingNeedleMaker.maker.skill/13)) end; table.insert(NetMendingNeedleMaker.activeMaking,{id="${MAKER_LOWER}_"..tostring(os.time()).."_"..tostring(math.random(1000,9999)),productType=pt,productName=d.name,cost=d.cost*qty,quantity=qty,food=0,prestige=d.prestige or 0,happiness=d.happiness or 0,daysRemaining=t,started=os.time()}); if _G.NotificationCenter then pcall(_G.NotificationCenter.notify,string.format("Izdelava: %d %s (%d dni)",qty,d.name,t),"info") end; return true end
function NetMendingNeedleMaker.completeMaking(m) local q=1.0+(NetMendingNeedleMaker.getQualityBonus()/100); if NetMendingNeedleMaker.maker then q=q+(NetMendingNeedleMaker.maker.skill/140) end; q=math.min(2.5,q); NetMendingNeedleMaker.productStock[m.productType]=(NetMendingNeedleMaker.productStock[m.productType] or 0)+m.quantity; NetMendingNeedleMaker.totalProducts=NetMendingNeedleMaker.totalProducts+m.quantity; if m.prestige>0 and _G.state and _G.state.happiness then _G.state.happiness=math.min(100,_G.state.happiness+m.prestige) end; if m.happiness>0 and _G.state and _G.state.happiness then _G.state.happiness=math.min(100,_G.state.happiness+m.happiness) end; if NetMendingNeedleMaker.maker then NetMendingNeedleMaker.maker.itemsMade=NetMendingNeedleMaker.maker.itemsMade+m.quantity; if math.random()<0.25 then NetMendingNeedleMaker.maker.skill=math.min(100,NetMendingNeedleMaker.maker.skill+1) end end; if _G.NotificationCenter then pcall(_G.NotificationCenter.notify,string.format("IglA izdelan: %d %s (kakovost: %.1f)",m.quantity,m.productName,q),"success") end; if _G.GameEventBus then pcall(_G.GameEventBus.publish,"${MAKER_LOWER}.completed",{productName=m.productName,prestige=m.prestige,happiness:m.happiness}) end end
function NetMendingNeedleMaker.update(dt) if not _G.state then return end; NetMendingNeedleMaker.dayTimer=NetMendingNeedleMaker.dayTimer+dt; if NetMendingNeedleMaker.dayTimer>=30 then NetMendingNeedleMaker.dayTimer=0; for i=#NetMendingNeedleMaker.activeMaking,1,-1 do local m=NetMendingNeedleMaker.activeMaking[i]; m.daysRemaining=m.daysRemaining-1; if m.daysRemaining<=0 then NetMendingNeedleMaker.completeMaking(m); table.remove(NetMendingNeedleMaker.activeMaking,i) end end; local tu=0; for _,bd in ipairs(NetMendingNeedleMaker.buildings) do local d=BUILDINGS[bd.type]; if d and d.upkeep then tu=tu+d.upkeep end end; if NetMendingNeedleMaker.maker then tu=tu+15 end; if tu>0 and _G.state then _G.state.gold=math.max(0,(_G.state.gold or 0)-tu) end end end
function NetMendingNeedleMaker.getStats() return {ironStock=NetMendingNeedleMaker.ironStock,bronzeStock=NetMendingNeedleMaker.bronzeStock,woodStock=NetMendingNeedleMaker.woodStock,leatherStock=NetMendingNeedleMaker.leatherStock,silverStock=NetMendingNeedleMaker.silverStock,goldStock=NetMendingNeedleMaker.goldStock,jewelStock=NetMendingNeedleMaker.jewelStock,pearlStock=NetMendingNeedleMaker.pearlStock,productStock=NetMendingNeedleMaker.productStock,numBuildings=#NetMendingNeedleMaker.buildings,hasMaker=NetMendingNeedleMaker.maker~=nil,makerName=NetMendingNeedleMaker.maker and NetMendingNeedleMaker.maker.name or "—",makerSkill=NetMendingNeedleMaker.maker and NetMendingNeedleMaker.maker.skill or 0,activeMaking=#NetMendingNeedleMaker.activeMaking,totalProducts=NetMendingNeedleMaker.totalProducts} end
return NetMendingNeedleMaker
